// Ganti isi gacha Wallpaper dengan 4 gambar baru, hapus wallpaper lama (yang berat/ngelag).
// Jalankan dari ~/komikita:   node patch-gacha-wallpaper.js
const fs = require('fs');
const path = require('path');
const rd = (f) => fs.readFileSync(f, 'utf8');
const wr = (f, s) => fs.writeFileSync(f, s);
let fail = 0;
const step = (name, fn) => { try { const r = fn(); console.log((r === 'skip' ? 'SKIP  ' : 'OK    ') + name); } catch (e) { fail++; console.log('GAGAL ' + name + ' -> ' + e.message); } };

const IMG = {"tunjuk-hati": "", "senyum-ceria": "", "hening-monokrom": "", "penguasa-bayangan": ""};

step('tulis 4 gambar baru ke public/wallpapers', () => {
  fs.mkdirSync('public/wallpapers', { recursive: true });
  for (const [k, b64] of Object.entries(IMG)) fs.writeFileSync('public/wallpapers/' + k + '.webp', Buffer.from(b64, 'base64'));
});

step('hapus wallpaper lama di public/wallpapers', () => {
  const keep = new Set(Object.keys(IMG).map((k) => k + '.webp'));
  let n = 0;
  for (const f of fs.readdirSync('public/wallpapers')) {
    if (keep.has(f)) continue;
    fs.rmSync(path.join('public/wallpapers', f), { recursive: true, force: true }); n++;
  }
  if (!n) return 'skip';
});

step('lib/wallpapers.ts: katalog baru', () => {
  const f = 'lib/wallpapers.ts';
  let s = rd(f);
  if (s.includes("'penguasa-bayangan': { nama: 'Penguasa Bayangan', rarity: 'Legendary', grad: 'linear-gradient(180deg,#0a0204,#5a0f1a)', url: '/wallpapers/penguasa-bayangan.webp'")) return 'skip';

  // field baru: pos = posisi crop gambar (supaya wajah tidak terpotong di banner lebar)
  s = s.replace(/  url\?: string;[^\n]*\n/, "  url?: string;   // gambar anime: /public/wallpapers/<key>.webp\n  pos?: string;   // posisi crop saat dipotong lebar (background-position), mis. 'center 30%'\n");

  const catalog =
"export const WALLPAPER_CATALOG: Record<string, WallpaperItem> = {\n" +
"  // Hanya 4 wallpaper (satu per rarity). Gambar diam .webp ringan di /public/wallpapers.\n" +
"  'tunjuk-hati':       { nama: 'Tunjuk Hati',       rarity: 'Normal',    grad: 'linear-gradient(180deg,#f7c6d9,#ffeef4)', url: '/wallpapers/tunjuk-hati.webp',       pos: 'center 35%' },\n" +
"  'senyum-ceria':      { nama: 'Senyum Ceria',      rarity: 'Rare',      grad: 'linear-gradient(180deg,#f3b6cf,#e8e8ea)', url: '/wallpapers/senyum-ceria.webp',      pos: 'center 40%' },\n" +
"  'hening-monokrom':   { nama: 'Hening Monokrom',   rarity: 'Epic',      grad: 'linear-gradient(180deg,#111,#3a3a3a)',    url: '/wallpapers/hening-monokrom.webp',   pos: 'center 42%' },\n" +
"  'penguasa-bayangan': { nama: 'Penguasa Bayangan', rarity: 'Legendary', grad: 'linear-gradient(180deg,#0a0204,#5a0f1a)', url: '/wallpapers/penguasa-bayangan.webp', pos: 'center 24%' },\n" +
"};\n";
  const reCat = /export const WALLPAPER_CATALOG: Record<string, WallpaperItem> = \{[\s\S]*?\n\};\n/;
  if (!reCat.test(s)) throw new Error('blok WALLPAPER_CATALOG tidak ketemu');
  s = s.replace(reCat, () => catalog);

  // wpBg: satu gambar saja + gradien cadangan (tidak lagi memuat SVG lama)
  const reFn = /\/\*\*\n \* Nilai CSS `background` untuk wallpaper[\s\S]*?\nexport function wpBg\([\s\S]*?\n\}\n/;
  if (!reFn.test(s)) throw new Error('fungsi wpBg tidak ketemu');
  s = s.replace(reFn, () =>
"/** Nilai CSS `background` untuk wallpaper: satu gambar diam (webp) + gradien cadangan. Parameter kedua dipertahankan agar pemanggil lama tidak error. */\n" +
"export function wpBg(key: string | undefined | null, _animated = false): string {\n" +
"  const w = key ? WALLPAPER_CATALOG[key] : undefined;\n" +
"  if (!w) return '';\n" +
"  if (!w.url) return w.grad;\n" +
"  return 'url(' + w.url + ') ' + (w.pos || 'center') + '/cover, ' + w.grad;\n" +
"}\n");

  s = s.replace("desc: 'Pemandangan sederhana tanpa efek tambahan. Paling mudah didapat.'", "desc: 'Ilustrasi anime sederhana tanpa efek tambahan. Paling mudah didapat.'");
  s = s.replace("desc: 'Ilustrasi berlapis dengan detail lebih banyak, bingkai biru bercahaya.'", "desc: 'Ilustrasi anime dengan bingkai biru bercahaya.'");
  wr(f, s);
});

console.log(fail ? '\nAda ' + fail + ' langkah GAGAL, kirim output ini ke Claude.' : '\nSelesai. Lanjut: git add . && git commit -m "gacha wallpaper: 4 gambar baru" && git push origin main');
